<https://example.org/openevidence/questions/q_addison_disease_efficacy> a holon:ClinicalQuestionHolon ;
    oeq:questionText "How effective is prednisone compared with other agents for Addison Disease?" .

<https://example.org/openevidence/questions/q_addison_disease_efficacy-int> a rdf:type oegen:GeneratedFact ;
    oe:treats <https://example.org/openevidence/drugs/prednisone> ;
    oeq:disease <https://example.org/openevidence/diseases/addison_disease> ;
    confidence 0.38,
    level "Level-4",
    source <https://example.org/openevidence/sources/36102024>,
    effectiveness "inconclusive" .
